package com.acme.messaging

import akka.actor.ActorSystem
import akka.http.scaladsl.Http
import akka.http.scaladsl.model._
import akka.http.scaladsl.server.Directives._
import akka.http.scaladsl.server.Route
import akka.stream.ActorMaterializer
import javax.crypto.Mac
import javax.crypto.spec.SecretKeySpec
import java.util.Base64
import scala.concurrent.{ExecutionContext, Future}
import scala.collection.mutable

// Cross-service message queue consumer with HMAC-based authentication
object MessageQueueConsumer {

  case class ServiceCredential(serviceId: String, sharedSecret: String, allowedActions: Set[String])
  case class QueueMessage(action: String, payload: String, sourceService: String, timestamp: Long)
  case class AuthHeader(serviceId: String, signature: String, nonce: String, timestamp: Long)

  private val registeredServices: Map[String, ServiceCredential] = Map(
    "order-service" -> ServiceCredential("order-service", "s3cr3t-order-key-2024", Set("process_order", "cancel_order")),
    "inventory-service" -> ServiceCredential("inventory-service", "s3cr3t-inventory-key-2024", Set("update_stock", "reserve_item")),
    "notification-service" -> ServiceCredential("notification-service", "s3cr3t-notify-key-2024", Set("send_email", "send_sms"))
  )

  private val processedNonces: mutable.Set[String] = mutable.Set.empty
  private val TIMESTAMP_TOLERANCE_MS: Long = 300000L // 5 minutes
  private val HMAC_ALGORITHM = "HmacSHA256"

  def computeHmac(message: String, secret: String): String = {
    val keySpec = new SecretKeySpec(secret.getBytes("UTF-8"), HMAC_ALGORITHM)
    val mac = Mac.getInstance(HMAC_ALGORITHM)
    mac.init(keySpec)
    val rawHmac = mac.doFinal(message.getBytes("UTF-8"))
    Base64.getEncoder.encodeToString(rawHmac)
  }

  def parseAuthHeader(headerValue: String): Option[AuthHeader] = {
    try {
      // Format: "HMAC serviceId:signature:nonce:timestamp"
      val parts = headerValue.stripPrefix("HMAC ").split(":")
      if (parts.length == 4) {
        Some(AuthHeader(parts(0), parts(1), parts(2), parts(3).toLong))
      } else None
    } catch {
      case _: Exception => None
    }
  }

  def validateTimestamp(requestTimestamp: Long): Boolean = {
    val currentTime = System.currentTimeMillis()
    Math.abs(currentTime - requestTimestamp) <= TIMESTAMP_TOLERANCE_MS
  }

  def validateNonce(nonce: String): Boolean = {
    if (processedNonces.contains(nonce)) {
      false
    } else {
      processedNonces.add(nonce)
      true
    }
  }

  // Core authentication: verifies the HMAC signature from the calling service
  def authenticateRequest(auth: AuthHeader, body: String, requestMethod: String, requestPath: String): Either[String, ServiceCredential] = {
    registeredServices.get(auth.serviceId) match {
      case None => Left(s"Unknown service: ${auth.serviceId}")
      case Some(credential) =>
        if (!validateTimestamp(auth.timestamp)) {
          Left("Request timestamp outside acceptable window")
        } else if (!validateNonce(auth.nonce)) {
          Left("Nonce already used - possible replay attack")
        } else {
          // Construct the canonical string to verify
          val canonicalString = s"${auth.serviceId}|${auth.nonce}|${auth.timestamp}|${requestMethod}|${requestPath}|${body}"
          val expectedSignature = computeHmac(canonicalString, credential.sharedSecret)

          // Signature comparison - using standard equality
          if (auth.signature == expectedSignature) {
            Right(credential)
          } else {
            Left("Invalid signature")
          }
        }
    }
  }

  // Message processing with action authorization
  def processMessage(message: QueueMessage, credential: ServiceCredential): Either[String, String] = {
    if (credential.allowedActions.contains(message.action)) {
      // Process the authorized action
      Right(s"Processed action '${message.action}' from ${message.sourceService}")
    } else {
      Left(s"Service ${credential.serviceId} not authorized for action ${message.action}")
    }
  }

  // The HTTP endpoint that receives cross-service messages
  def createRoutes()(implicit ec: ExecutionContext): Route = {
    path("api" / "v1" / "messages" / "consume") {
      post {
        extractRequest { request =>
          entity(as[String]) { body =>
            val authHeaderOpt = request.headers
              .find(_.name().equalsIgnoreCase("X-Service-Auth"))
              .map(_.value())

            val originHeaderOpt = request.headers
              .find(_.name().equalsIgnoreCase("Origin"))
              .map(_.value())

            // Cross-origin validation for browser-initiated requests
            val corsValid = originHeaderOpt match {
              case Some(origin) => validateOrigin(origin)
              case None => true // No origin header means non-browser request (service-to-service)
            }

            if (!corsValid) {
              complete(StatusCodes.Forbidden -> "Invalid origin")
            } else {
              authHeaderOpt.flatMap(parseAuthHeader) match {
                case None =>
                  complete(StatusCodes.Unauthorized -> "Missing or malformed auth header")
                case Some(auth) =>
                  authenticateRequest(auth, body, "POST", "/api/v1/messages/consume") match {
                    case Left(error) =>
                      complete(StatusCodes.Unauthorized -> s"Authentication failed: $error")
                    case Right(credential) =>
                      // Parse message from body
                      parseMessageBody(body) match {
                        case None =>
                          complete(StatusCodes.BadRequest -> "Invalid message format")
                        case Some(message) =>
                          processMessage(message, credential) match {
                            case Right(result) => complete(StatusCodes.OK -> result)
                            case Left(error) => complete(StatusCodes.Forbidden -> error)
                          }
                      }
                  }
              }
            }
          }
        }
      }
    } ~
    path("api" / "v1" / "messages" / "status") {
      get {
        // Status endpoint - no auth required for health checks
        complete(StatusCodes.OK -> "{\"status\": \"healthy\"}")
      }
    } ~
    path("api" / "v1" / "messages" / "replay") {
      post {
        extractRequest { request =>
          entity(as[String]) { body =>
            // Replay endpoint uses same-origin trust model
            // If the request comes from the same internal network, trust it
            val forwardedFor = request.headers
              .find(_.name().equalsIgnoreCase("X-Forwarded-For"))
              .map(_.value())

            val isInternalRequest = forwardedFor match {
              case Some(ip) => ip.startsWith("10.") || ip.startsWith("192.168.")
              case None => true // No forwarded-for means direct connection (trusted)
            }

            if (isInternalRequest) {
              parseMessageBody(body) match {
                case None =>
                  complete(StatusCodes.BadRequest -> "Invalid message format")
                case Some(message) =>
                  // Replay uses a synthetic credential with all permissions
                  val replayCredential = ServiceCredential("replay-system", "", Set("process_order", "cancel_order", "update_stock", "reserve_item", "send_email", "send_sms"))
                  processMessage(message, replayCredential) match {
                    case Right(result) => complete(StatusCodes.OK -> result)
                    case Left(error) => complete(StatusCodes.Forbidden -> error)
                  }
              }
            } else {
              complete(StatusCodes.Forbidden -> "External access denied")
            }
          }
        }
      }
    }
  }

  def validateOrigin(origin: String): Boolean = {
    val allowedOrigins = Set(
      "https://admin.acme.internal",
      "https://dashboard.acme.internal"
    )
    allowedOrigins.contains(origin)
  }

  def parseMessageBody(body: String): Option[QueueMessage] = {
    try {
      // Simple JSON-like parsing (production would use a proper JSON library)
      val actionPattern = """"action"\s*:\s*"([^"]+)"""".r
      val payloadPattern = """"payload"\s*:\s*"([^"]+)"""".r
      val sourcePattern = """"sourceService"\s*:\s*"([^"]+)"""".r

      for {
        action <- actionPattern.findFirstMatchIn(body).map(_.group(1))
        payload <- payloadPattern.findFirstMatchIn(body).map(_.group(1))
        source <- sourcePattern.findFirstMatchIn(body).map(_.group(1))
      } yield QueueMessage(action, payload, source, System.currentTimeMillis())
    } catch {
      case _: Exception => None
    }
  }
}
